// The exit test's local stand-in for the demo image's Caddy gate
// (deploy/demo/Caddyfile.template's shape, in one dependency-free node
// server): the built front door from disk, the core behind it on /api and
// /healthz, and basic authentication on the pages and the demo mint routes
// and on nothing else, exactly the gate's own split. The phrase arrives in
// the FD_EXIT_PHRASE environment variable, generated by the exit script,
// held in its shell and this process's environment alone: nothing prints it
// and nothing writes it to a file.
//
//   FD_EXIT_DIST      the built app's dist directory (served at /)
//   FD_EXIT_UPSTREAM  the core's loopback address (proxied at /api, /healthz)
//   FD_EXIT_PORT      this server's port
//   FD_EXIT_PHRASE    the gate's phrase (user "demo")
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, normalize } from "node:path";

const dist = process.env.FD_EXIT_DIST ?? "";
const upstream = process.env.FD_EXIT_UPSTREAM ?? "http://127.0.0.1:5673";
const port = Number(process.env.FD_EXIT_PORT ?? 5672);
const phrase = process.env.FD_EXIT_PHRASE ?? "";
if (dist === "" || phrase === "") {
  process.stderr.write("serve: FD_EXIT_DIST and FD_EXIT_PHRASE are required\n");
  process.exit(1);
}

const MIME = new Map([
  [".html", "text/html; charset=utf-8"],
  [".js", "text/javascript; charset=utf-8"],
  [".css", "text/css; charset=utf-8"],
  [".svg", "image/svg+xml"],
  [".png", "image/png"],
  [".woff2", "font/woff2"],
  [".json", "application/json"],
]);

// The gate: pages and the demo mint ask for the phrase, the rest of /api and
// /healthz do not (the gate's own split: a staff route behind a bearer is the
// core's law, and the health leg answers the platform unauthenticated).
function gated(path) {
  if (path.startsWith("/api/")) {
    return path.startsWith("/api/v1/demo/");
  }
  return path !== "/healthz";
}

function gateOk(header) {
  if (typeof header !== "string" || !header.startsWith("Basic ")) return false;
  let decoded = "";
  try {
    decoded = Buffer.from(header.slice(6), "base64").toString("utf8");
  } catch {
    return false;
  }
  const separator = decoded.indexOf(":");
  if (separator < 0) return false;
  return decoded.slice(0, separator) === "demo" && decoded.slice(separator + 1) === phrase;
}

function readBody(request) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    request.on("data", (chunk) => chunks.push(chunk));
    request.on("end", () => resolve(Buffer.concat(chunks)));
    request.on("error", reject);
  });
}

async function proxy(request, response) {
  const url = new URL(request.url ?? "/", upstream);
  // The proxy forwards the caller's headers the way Caddy's reverse_proxy
  // does (a staff route's bearer and org ride through), minus the hop-by-hop
  // and framing headers a new hop sets itself, and it replaces
  // X-Forwarded-For with the address it saw, the template's own discipline.
  const headers = {};
  const hopByHop = new Set([
    "host",
    "connection",
    "keep-alive",
    "transfer-encoding",
    "upgrade",
    "content-length",
    "x-forwarded-for",
    "x-forwarded-proto",
    "x-forwarded-host",
  ]);
  for (const [name, value] of Object.entries(request.headers)) {
    if (!hopByHop.has(name.toLowerCase())) headers[name] = value;
  }
  headers["x-forwarded-for"] = request.socket.remoteAddress ?? "";
  const proxied = await fetch(url, {
    method: request.method,
    headers,
    body: ["GET", "HEAD"].includes(request.method) ? undefined : await readBody(request),
    // The exit walk wants the honest status: no silent redirect following.
    redirect: "manual",
  }).catch(() => null);
  if (proxied === null) {
    response.writeHead(502).end();
    return;
  }
  const responseHeaders = Object.fromEntries(proxied.headers.entries());
  delete responseHeaders["content-encoding"];
  delete responseHeaders["content-length"];
  delete responseHeaders["transfer-encoding"];
  response.writeHead(proxied.status, responseHeaders);
  response.end(Buffer.from(await proxied.arrayBuffer()));
}

const server = createServer((request, response) => {
  const path = (request.url ?? "/").split("?")[0];
  if (gated(path) && !gateOk(request.headers.authorization)) {
    response.writeHead(401, { "www-authenticate": 'Basic realm="demo", charset="UTF-8"' });
    response.end();
    return;
  }
  if (path === "/healthz" || path.startsWith("/api/")) {
    void proxy(request, response);
    return;
  }
  // The app: static files from dist, index.html at the root (the SPA's one
  // page; no history routes exist yet, so try_files is the root alone).
  const relative = path === "/" ? "index.html" : normalize(path).replace(/^([/\\])+/, "");
  const file = join(dist, relative);
  if (!file.startsWith(dist)) {
    response.writeHead(403).end();
    return;
  }
  readFile(file)
    .then((body) => {
      response.writeHead(200, {
        "content-type": MIME.get(extname(file)) ?? "application/octet-stream",
      });
      response.end(body);
    })
    .catch(() => {
      response.writeHead(404).end();
    });
});

server.listen(port, "127.0.0.1", () => {
  process.stdout.write(`front-door exit gate on 127.0.0.1:${port}\n`);
});
